"""Chaos injection orchestrator with scheduling and verification."""

from __future__ import annotations

import asyncio
import random
import time
from collections.abc import AsyncIterator, Callable
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Protocol

from pydantic import BaseModel, Field, ValidationError


class FaultType(str, Enum):
    CRASH = "crash"
    PARTITION = "partition"
    DELAY = "delay"
    REORDER = "reorder"
    CORRUPT = "corrupt"
    EXHAUST = "exhaust"
    CLOCK_SKEW = "clock_skew"


class FaultSeverity(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class FaultSpec(BaseModel):
    """Schema-validated fault injection specification."""
    fault_type: FaultType
    target: str  # Node ID or link identifier
    severity: FaultSeverity = FaultSeverity.MEDIUM
    duration_ms: int = Field(default=100, ge=1, le=600000)
    probability: float = Field(default=1.0, ge=0.0, le=1.0)
    params: dict[str, Any] = Field(default_factory=dict)

    @classmethod
    def validate_spec(cls, data: dict[str, Any]) -> "FaultSpec":
        """Validate and construct a fault spec."""
        try:
            return cls(**data)
        except ValidationError as e:
            raise ValueError(f"Invalid fault spec: {e}") from e


class ChaosTarget(Protocol):
    """Protocol for chaos-injectable system components."""

    async def inject_fault(self, spec: FaultSpec) -> None: ...
    async def verify_health(self) -> dict[str, Any]: ...
    async def recover(self, spec: FaultSpec) -> None: ...


@dataclass(slots=True)
class InjectionResult:
    """Result of a single fault injection."""
    spec: FaultSpec
    started_at: float
    completed_at: float
    success: bool
    error: str | None = None
    observations: dict[str, Any] = field(default_factory=dict)

    @property
    def duration_ms(self) -> float:
        return (self.completed_at - self.started_at) * 1000


class InjectionScheduler:
    """Deterministic and stochastic fault scheduling strategies."""

    def __init__(self, seed: int | None = None) -> None:
        self._rng = random.Random(seed)

    async def schedule(
        self,
        faults: list[FaultSpec],
        strategy: str = "sequential",
    ) -> AsyncIterator[FaultSpec]:
        """Yield faults according to the selected strategy."""
        if strategy == "sequential":
            for fault in faults:
                yield fault
                await asyncio.sleep(0.01)  # Allow system to settle
        elif strategy == "random":
            shuffled = faults.copy()
            self._rng.shuffle(shuffled)
            for fault in shuffled:
                yield fault
                await asyncio.sleep(self._rng.uniform(0.01, 0.1))
        elif strategy == "burst":
            # Inject all faults nearly simultaneously
            for fault in faults:
                yield fault
            await asyncio.sleep(0.001)
        elif strategy == "staggered":
            for i, fault in enumerate(faults):
                yield fault
                await asyncio.sleep(0.1 * (i + 1))
        else:
            raise ValueError(f"Unknown scheduling strategy: {strategy}")


class ChaosEngine:
    """Orchestrates chaos injection with health verification."""

    def __init__(
        self,
        targets: dict[str, ChaosTarget],
        scheduler: InjectionScheduler | None = None,
        verify_after_each: bool = True,
    ) -> None:
        self._targets = targets
        self._scheduler = scheduler or InjectionScheduler()
        self._verify_after_each = verify_after_each
        self._results: list[InjectionResult] = []
        self._active_faults: dict[str, FaultSpec] = {}

    async def run(
        self,
        faults: list[FaultSpec],
        strategy: str = "sequential",
        stop_on_failure: bool = False,
    ) -> list[InjectionResult]:
        """Execute the chaos injection campaign."""
        async for fault in self._scheduler.schedule(faults, strategy):
            result = await self._inject_single(fault)
            self._results.append(result)

            if not result.success and stop_on_failure:
                break

            if self._verify_after_each and result.success:
                await self._verify_system_health()

        return self._results

    async def _inject_single(self, spec: FaultSpec) -> InjectionResult:
        """Inject a single fault and measure its impact."""
        started = time.monotonic()
        result = InjectionResult(
            spec=spec,
            started_at=started,
            completed_at=started,
            success=False,
        )

        target = self._targets.get(spec.target)
        if target is None:
            result.error = f"Unknown target: {spec.target}"
            result.completed_at = time.monotonic()
            return result

        try:
            # Pre-injection health check
            pre_health = await target.verify_health()

            # Inject the fault
            await target.inject_fault(spec)
            self._active_faults[spec.target] = spec

            # Wait for the fault duration
            await asyncio.sleep(spec.duration_ms / 1000)

            # Post-injection observation
            post_health = await target.verify_health()
            result.observations = {
                "pre_health": pre_health,
                "post_health": post_health,
            }

            # Recover from the fault
            await target.recover(spec)
            del self._active_faults[spec.target]

            result.success = True
        except Exception as e:
            result.error = str(e)
            # Attempt recovery even on failure
            try:
                await target.recover(spec)
            except Exception:
                pass

        result.completed_at = time.monotonic()
        return result

    async def _verify_system_health(self) -> None:
        """Verify all targets are healthy after fault injection."""
        for target_id, target in self._targets.items():
            health = await target.verify_health()
            if not health.get("healthy", False):
                raise RuntimeError(
                    f"System unhealthy after fault injection: "
                    f"target={target_id}, health={health}"
                )

    def get_results(self) -> list[InjectionResult]:
        """Return all injection results."""
        return self._results.copy()

    def get_failure_rate(self) -> float:
        """Calculate the fault injection failure rate."""
        if not self._results:
            return 0.0
        failures = sum(1 for r in self._results if not r.success)
        return failures / len(self._results)

    def get_median_recovery_time_ms(self) -> float:
        """Calculate median recovery time across successful injections."""
        durations = [
            r.duration_ms for r in self._results if r.success
        ]
        if not durations:
            return 0.0
        durations.sort()
        mid = len(durations) // 2
        if len(durations) % 2 == 0:
            return (durations[mid - 1] + durations[mid]) / 2
        return durations[mid]